import{_ as i,J as t,b as a,e as n,a8 as r,f as d,L as s}from"./chunks/framework.CumEd6mW.js";const h=JSON.parse('{"title":"GR32_Math","description":"","frontmatter":{"layout":"doc","docType":"api","unit":"GR32_Math","entity":"GR32_Math","kind":"Unit","summary":"Provides fixed-point mathematics, fast approximation algorithms, floating-point modulo routines, trigonometry helpers, and prefix-sum operations.","title":"GR32_Math","date":1788887278000,"authors":[],"tags":[],"head":[]},"headers":[],"relativePath":"api/GR32_Math/index.md","filePath":"api/GR32_Math/index.md","lastUpdated":1788887278000,"timestamp":1788887278000,"datetime":"2026-09-08T17:07:58.000Z"}'),c={name:"api/GR32_Math/index.md"};function l(p,e,m,u,g,f){const o=t("ApiMembers");return a(),n("div",null,[e[0]||(e[0]=r('<h2 id="description" tabindex="-1">Description <a class="header-anchor" href="#description" aria-label="Permalink to &quot;Description&quot;">​</a></h2><p>The <code>GR32_Math</code> unit contains general mathematical utilities optimized for graphics programming and high-performance calculations in Graphics32.</p><p>Key features include:</p><ul><li><strong>Fixed-Point Arithmetic</strong>: Fast floor, ceiling, rounding, multiplication, division, reciprocal (<code>OneOver</code>), square, square root (<code>FixedSqrtLP</code>, <code>FixedSqrtHP</code>), and linear interpolation (<code>FixedCombine</code>) for <code>TFixed</code> [16:16] fixed-point numbers.</li><li><strong>Trigonometry &amp; Fast Approximations</strong>: Multi-signature <code>SinCos</code> and <code>Hypot</code> routines, as well as fast floating-point square root (<code>FastSqrt</code>, <code>FastSqrtBab1</code>, <code>FastSqrtBab2</code>) and inverse square root (<code>FastInvSqrt</code>) approximations.</li><li><strong>Modulo &amp; Remainder Functions</strong>: High-precision floating-point modulo operations including <code>FMod</code> (truncating division modulo), <code>FloatMod</code> (floored division modulo), and <code>FloatRemainder</code> (rounded division remainder).</li><li><strong>Miscellaneous Math</strong>: Bitwise power-of-two tests and rounding (<code>IsPowerOf2</code>, <code>PrevPowerOf2</code>, <code>NextPowerOf2</code>), integer <code>MulDiv</code>, <code>DivMod</code>, non-overflow integer <code>Average</code>, and fast <code>Sign</code>.</li><li><strong>Cumulative Sum / Prefix Sum</strong>: CPU-optimized <code>CumSum</code> routine for prefix-sum arrays.</li></ul>',4)),d("p",null,[s(o,{type:"members"})])])}const x=i(c,[["render",l]]);export{h as __pageData,x as default};
